parameters.text:
=You are an ETL data assistant. Analyze and clean the following student enrollment record. Fix obvious typos in city names or course names and return a clean JSON object.
Record: {{ JSON.stringify($json) }}

Return ONLY the structured JSON with fields: Student_ID, Name, Email, Phone, Course, Fee_Paid, City, Enrolled_Date.

parameters.jsCode:
// Robust Data Sanitization & Standardization
function toTitleCase(str) {
  if (!str) return '';
  return str.toString().toLowerCase().trim().split(/\s+/).map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
}

function isValidEmail(email) {
  if (!email) return false;
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email.toString().trim());
}

function normalizeFeePaid(fee) {
  if (!fee) return 'No';
  const clean = fee.toString().trim().toLowerCase();
  if (['yes', 'y', 'true', 'paid', '1'].includes(clean)) return 'Yes';
  return 'No';
}

function normalizeCourse(course) {
  if (!course) return '';
  const clean = course.toString().trim().toLowerCase();
  if (clean === 'python') return 'Python';
  if (clean === 'ml' || clean === 'machine learning') return 'Machine Learning';
  if (clean === 'ds' || clean === 'data science') return 'Data Science';
  return toTitleCase(course);
}

return $input.all().map(item => {
  // Support either direct JSON or parsed response from LLM chain
  let raw = item.json;
  if (raw.text && typeof raw.text === 'string') {
    try {
      const parsed = JSON.parse(raw.text.replace(/```json|```/g, '').trim());
      raw = { ...raw, ...parsed };
    } catch (e) {
      // fallback to original raw
    }
  }

  const name = toTitleCase(raw.Name);
  const email = (raw.Email || '').toString().trim().toLowerCase();
  const city = toTitleCase(raw.City) || 'Not Provided';
  const course = normalizeCourse(raw.Course);
  const feePaid = normalizeFeePaid(raw.Fee_Paid);

  const rawPhone = (raw.Phone || '').toString().trim();
  const phone = rawPhone.length === 10 && /^\d+$/.test(rawPhone) ? rawPhone : 'Invalid/Missing';
  const validEmail = isValidEmail(email);

  return {
    json: {
      Student_ID: raw.Student_ID || '',
      Name: name,
      Email: email,
      Phone: phone,
      Course: course,
      Fee_Paid: feePaid,
      City: city,
      Enrolled_Date: raw.Enrolled_Date || '',
      is_valid_email: validEmail
    }
  };
});
